// 1. Compile-Time Polymorphism (Function Overloading)

void print(int i) { /* int implementation */ }
void print(const char* s) { /* string implementation */ }
// Resolution: Done by the compiler based on argument types.
// Implementation: Name mangling creates unique internal function names.

// 2. Compile-Time Polymorphism (Templates/Static Duck Typing)

template <typename T>
T add(T a, T b) { return a + b; }
// Resolution: Compiler generates specialized code for used types (Monomorphization).
// Performance: High, often inlined code; no runtime overhead.

// 3. Runtime Polymorphism (Virtual Functions)

class Base {
public:
    virtual void draw() const = 0; // Requires vtable setup
    virtual ~Base() {} // Virtual destructor is crucial
};

class Derived : public Base {
public:
    void draw() const override { /* Derived implementation */ }
};

// 4. Implementation Detail: VTable and VPTR

// Memory layout of Derived object:
// [ VPTR (4/8 bytes) ] -> Points to VTable
// [ Member Data... ]

// VTable structure (per class):
// [ Address of ~Base() ]
// [ Address of draw() ]

// Cost: One extra pointer (VPTR) per object; indirection cost (lookup) at call site.
